const ICON_BACK = '<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5 7.67 11 8.5 11zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>';
const STAR_BIG = '<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>';
const LABEL = "本地表情";
const FAV = "\u0000fav";
const TAB_KEY = "qq-enhance-sticker-tab";
const ORDER_KEY = "qq-enhance-sticker-order";
const LAST_KEY = "qq-enhance-sticker-last";   // 关面板时是否停在本地表情页（重启/刷新后也记得）
// 表情面板里 QQ 自带的三个按钮，设置页可以分别隐藏
const NATIVE_TABS = [["showEmojiSearch", "搜索表情", "search"], ["showEmojiDefault", "默认表情", "default"], ["showEmojiFav", "我的收藏", "fav"]];
const ACTIVE_CLS = "tabs-container-item-active";

const CSS = `
#qe-sticker-view {
  position: fixed; z-index: 4500; display: none; flex-direction: column; box-sizing: border-box;
  overflow: hidden;
  background: transparent;
  color: var(--ll-on-glass, var(--text_primary, #222)); font-size: 13px;
}
#qe-sticker-view.is-open { display: flex; }
#qe-sticker-view .qe-sp-grid {
  flex: 1; overflow-y: auto; padding: 4px 8px 8px; display: grid; align-content: start;
  grid-template-columns: repeat(auto-fill, minmax(68px, 1fr)); grid-auto-rows: 68px; gap: 4px;
}
#qe-sticker-view .qe-sp-cell {
  position: relative; height: 68px; min-width: 0; padding: 6px; box-sizing: border-box; border-radius: 8px; cursor: pointer;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
#qe-sticker-view .qe-sp-cell:hover { background: var(--overlay_hover, rgba(127,127,127,.14)); }
/* 格子定死 68px、图片铺满格子再 contain：大图不会撑开格子叠到一起 */
#qe-sticker-view .qe-sp-cell img { display: block !important; width: 100% !important; height: 100% !important; max-width: none !important; max-height: none !important; object-fit: contain !important; pointer-events: none; }
#qe-sticker-view .qe-sp-star {
  position: absolute; top: 3px; right: 3px; width: 20px; height: 20px; border-radius: 6px;
  display: none; align-items: center; justify-content: center;
  color: var(--ll-on-glass-2, var(--text_secondary, #888)); background: rgba(127,127,127,.2);
}
#qe-sticker-view .qe-sp-cell:hover .qe-sp-star { display: flex; }
#qe-sticker-view .qe-sp-cell.is-fav .qe-sp-star { display: flex; color: #f5b400; background: transparent; }
#qe-sticker-view .qe-sp-star:hover { background: rgba(127,127,127,.32); }
#qe-sticker-view .qe-sp-title {
  grid-column: 1 / -1; padding: 4px 4px 2px; font-size: 12px;
  color: var(--ll-on-glass-2, var(--text_secondary, #888));
}
#qe-sticker-view .qe-sp-divide { flex: 0 0 1px; margin: 0 8px; background: rgba(127,127,127,.18); }
#qe-sticker-view .qe-sp-bar { display: flex; align-items: center; gap: 2px; padding: 6px 8px; flex: 0 0 auto; height: 48px; box-sizing: border-box; }
#qe-sticker-view .qe-sp-tabs { flex: 1; display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; }
#qe-sticker-view .qe-sp-tabs::-webkit-scrollbar { display: none; }
#qe-sticker-view .qe-sp-tab, #qe-sticker-view .qe-sp-act {
  flex: 0 0 auto; width: 36px; height: 36px; padding: 0; border: none; border-radius: 8px; cursor: pointer;
  display: flex; align-items: center; justify-content: center; background: transparent;
  color: var(--icon_primary, var(--ll-on-glass, currentColor)); font: inherit;
}
#qe-sticker-view .qe-sp-act { width: 28px; color: var(--ll-on-glass-2, var(--text_secondary, #888)); }
#qe-sticker-view .qe-sp-back { margin-right: 2px; }
#qe-sticker-view .qe-sp-tab img { width: 28px; height: 28px; object-fit: cover; border-radius: 6px; pointer-events: none; }
#qe-sticker-view .qe-sp-tab:hover, #qe-sticker-view .qe-sp-act:hover { background: var(--overlay_hover, rgba(127,127,127,.14)); }
#qe-sticker-view .qe-sp-tab.is-active { background: var(--overlay_active, rgba(var(--ll-brand-rgb, 0,153,255), .2)); }
#qe-sticker-view .qe-sp-tab.is-fav-tab.is-active { color: #f5b400; }
#qe-sticker-view .qe-sp-empty {
  grid-column: 1 / -1; padding: 40px 16px; text-align: center; line-height: 1.7;
  color: var(--ll-on-glass-2, var(--text_secondary, #888));
}
#qe-sticker-view .qe-sp-empty b { color: var(--ll-on-glass, var(--text_primary, #222)); font-weight: 600; }
/* 本地表情页打开时，把 QQ 自己的内容藏起来（面板底色和分类栏留着） */
body.qe-st-active .expression-panel .sticker-panel > :first-child,
body.qe-st-active .expression-panel .sticker-panel__pages,
body.qe-st-active .expression-panel .sticker-panel__divide,
body.qe-st-active .expression-panel .sticker-panel__bar { visibility: hidden !important; }
body[data-qe-hide-search] .expression-panel .tabs-container-item[aria-label="搜索表情"],
body[data-qe-hide-default] .expression-panel .tabs-container-item[aria-label="默认表情"],
body[data-qe-hide-fav] .expression-panel .tabs-container-item[aria-label="我的收藏"] { display: none !important; }
/* 切换按钮放在分类栏最前面（分类栏翻页也不动），不在可翻页的那一排里 */
.expression-panel .sticker-panel__bar > .qe-st-tab {
  flex: 0 0 auto; width: 36px; height: 36px; margin: 0 4px 0 10px; border-radius: 8px; cursor: pointer;
  display: flex; align-items: center; justify-content: center; align-self: center;
}
.expression-panel .sticker-panel__bar > .qe-st-tab:hover { background: var(--overlay_hover, rgba(127,127,127,.14)); }
.expression-panel .sticker-panel__bar > .qe-st-tab.tabs-container-item-active { background: var(--overlay_active, rgba(127,127,127,.2)); }
#qe-sticker-view .qe-sp-tab.is-dragging { opacity: .35; }
#qe-sticker-view .qe-sp-tab.is-drop-before { box-shadow: inset 2px 0 0 var(--ll-brand, var(--brand_standard, #0099ff)); }
#qe-sticker-view .qe-sp-tab.is-drop-after { box-shadow: inset -2px 0 0 var(--ll-brand, var(--brand_standard, #0099ff)); }
.expression-panel .qe-st-tab { color: var(--icon_primary, currentColor); }
.expression-panel .qe-st-tab svg { width: 24px; height: 24px; display: block; }
`;

function appimg(p) {
    return "appimg://" + encodeURI(String(p).replace(/\\/g, "/")).replace(/#/g, "%23").replace(/\?/g, "%3F");
}

function installStickers(api, getConfig, toast) {
    let data = { groups: [], favs: [], root: "" };
    let favSet = new Set();
    let tab = localStorage.getItem(TAB_KEY) || FAV;
    let view = null, grid = null, tabsEl = null;
    let active = false;          // 本地表情页是否打开
    // 上次关面板时停在本地表情页：下次打开直接回到这里。存进 localStorage，刷新/重启也记得
    let lastOursVal = localStorage.getItem(LAST_KEY) === "1";
    const setLast = v => { lastOursVal = !!v; try { localStorage.setItem(LAST_KEY, v ? "1" : "0"); } catch (e) {} };
    let panelWasOpen = false;
    let recheck = 0, recheckLeft = 0;
    let raf = 0;

    const style = document.createElement("style");
    style.id = "qq-enhance-sticker-style";
    style.textContent = CSS;
    (document.head || document.documentElement).appendChild(style);

    function peerNow() {
        try {
            const area = document.querySelector(".chat-msg-area");
            for (const inst of (area && area.__VUE__) || []) {
                const p = inst && inst.props && inst.props.peer;
                if (p && p.peerUid) return { chatType: p.chatType, peerUid: String(p.peerUid), guildId: p.guildId ? String(p.guildId) : "" };
            }
            const m = document.querySelector(".chat-msg-area .message");
            const rec = m && m.__VUE__ && m.__VUE__[0] && m.__VUE__[0].props && m.__VUE__[0].props.msgRecord;
            if (rec && rec.peerUid) return { chatType: rec.chatType, peerUid: String(rec.peerUid), guildId: rec.guildId ? String(rec.guildId) : "" };
        } catch (e) {}
        return null;
    }

    function stickerPanel() {
        const sp = document.querySelector(".chat-input-area .expression-panel .sticker-panel") || document.querySelector(".expression-panel .sticker-panel");
        if (!sp) return null;
        const r = sp.getBoundingClientRect();
        return r.width > 100 && r.height > 100 ? sp : null;
    }

    function loadOrder() {
        try { return JSON.parse(localStorage.getItem(ORDER_KEY) || "[]"); } catch (e) { return []; }
    }
    function sortGroups() {
        const order = loadOrder();
        const rank = name => { const i = order.indexOf(name); return i < 0 ? 1e6 : i; };
        data.groups = data.groups.map((g, i) => [g, i]).sort((a, b) => (rank(a[0].name) - rank(b[0].name)) || (a[1] - b[1])).map(x => x[0]);
    }
    function moveGroup(from, to, after) {
        const names = data.groups.map(g => g.name);
        if (from === to) return;
        names.splice(names.indexOf(from), 1);
        let i = names.indexOf(to);
        if (after) i++;
        names.splice(i, 0, from);
        try { localStorage.setItem(ORDER_KEY, JSON.stringify(names)); } catch (e) {}
        sortGroups();
        render();
    }

    async function reload() {
        try { data = await api.stickerList(); } catch (e) { data = { groups: [], favs: [], root: "" }; }
        sortGroups();
        favSet = new Set(data.favs || []);
        if (tab !== FAV && !data.groups.some(g => g.name === tab)) tab = FAV;
        if (active) render();
    }

    function build() {
        if (view) return;
        view = document.createElement("div");
        view.id = "qe-sticker-view";
        view.innerHTML = '<div class="qe-sp-grid"></div><div class="qe-sp-divide"></div>' +
            '<div class="qe-sp-bar">' +
            '<button type="button" class="qe-sp-tab qe-sp-back" data-act="back" title="切回 QQ 表情">' + ICON_BACK + '</button>' +
            '<div class="qe-sp-tabs"></div>' +
            '<button type="button" class="qe-sp-act" data-act="refresh" title="刷新">' + ICON_REFRESH + '</button>' +
            '<button type="button" class="qe-sp-act" data-act="open" title="打开表情文件夹">' + ICON_FOLDER + '</button></div>';
        grid = view.querySelector(".qe-sp-grid");
        tabsEl = view.querySelector(".qe-sp-tabs");
        document.body.appendChild(view);

        // 面板外点击会让 QQ 收起表情面板；内容层不在面板 DOM 里，得挡住 mousedown，免得 QQ 以为点到了外面
        view.addEventListener("mousedown", e => e.stopPropagation());
        view.addEventListener("click", e => {
            e.stopPropagation();
            const act = e.target.closest("[data-act]");
            if (act) {
                if (act.dataset.act === "back") { setLast(false); deactivate(); }
                else if (act.dataset.act === "open") api.stickerOpenDir();
                else reload().then(() => toast("已刷新"));
                return;
            }
            const t = e.target.closest(".qe-sp-tab");
            if (t) { tab = t.dataset.tab; localStorage.setItem(TAB_KEY, tab); render(); grid.scrollTop = 0; return; }
            const cell = e.target.closest(".qe-sp-cell");
            if (!cell) return;
            if (e.target.closest(".qe-sp-star")) { toggleFav(cell.dataset.path); return; }
            send(cell, !(e.ctrlKey || e.shiftKey));
        });
        // 拖动文件夹按钮调整分组顺序（收藏固定在最前，不参与）
        let dragName = null;
        const clearMarks = () => tabsEl.querySelectorAll(".is-drop-before, .is-drop-after").forEach(n => n.classList.remove("is-drop-before", "is-drop-after"));
        const dropTarget = e => {
            const b = e.target.closest && e.target.closest(".qe-sp-tabs .qe-sp-tab");
            if (!b || b.dataset.tab === FAV) return null;
            const r = b.getBoundingClientRect();
            return { b, after: e.clientX > r.left + r.width / 2 };
        };
        tabsEl.addEventListener("dragstart", e => {
            const b = e.target.closest(".qe-sp-tab");
            if (!b || b.dataset.tab === FAV) { e.preventDefault(); return; }
            dragName = b.dataset.tab;
            b.classList.add("is-dragging");
            e.dataTransfer.effectAllowed = "move";
            e.dataTransfer.setData("text/plain", dragName);
        });
        tabsEl.addEventListener("dragover", e => {
            if (!dragName) return;
            e.preventDefault();
            e.stopPropagation();
            clearMarks();
            const d = dropTarget(e);
            if (d && d.b.dataset.tab !== dragName) d.b.classList.add(d.after ? "is-drop-after" : "is-drop-before");
            // 拖到两头时自动横向滚动
            const r = tabsEl.getBoundingClientRect();
            if (e.clientX < r.left + 24) tabsEl.scrollLeft -= 8;
            else if (e.clientX > r.right - 24) tabsEl.scrollLeft += 8;
        });
        tabsEl.addEventListener("drop", e => {
            if (!dragName) return;
            e.preventDefault();
            e.stopPropagation();
            const d = dropTarget(e);
            const from = dragName;
            dragName = null;
            clearMarks();
            if (d) moveGroup(from, d.b.dataset.tab, d.after);
        });
        tabsEl.addEventListener("dragend", () => {
            dragName = null;
            clearMarks();
            tabsEl.querySelectorAll(".is-dragging").forEach(n => n.classList.remove("is-dragging"));
        });

        view.addEventListener("contextmenu", e => {
            e.preventDefault();
            e.stopPropagation();
            const cell = e.target.closest(".qe-sp-cell");
            if (cell) toggleFav(cell.dataset.path);
        });
        // QQ 的表情面板一看到滚动/滚轮就收起（它在 document 上监听）。
        // 本地表情页里的滚动在 window 捕获阶段就截住，不让 QQ 看到；底栏的滚轮在这里顺手换成横向滚动。
        const guard = e => {
            if (!view || !(e.target instanceof Node) || !view.contains(e.target)) return;
            if (e.type === "wheel" && e.target.closest && e.target.closest(".qe-sp-bar")) {
                tabsEl.scrollLeft += e.deltaY || e.deltaX;
                e.preventDefault();
            }
            e.stopPropagation();
        };
        addEventListener("scroll", guard, true);
        addEventListener("wheel", guard, { capture: true, passive: false });
    }

    async function toggleFav(p) {
        const on = !favSet.has(p);
        try {
            data.favs = await api.stickerFav(p, on);
            favSet = new Set(data.favs);
            toast(on ? "已收藏" : "已取消收藏");
        } catch (e) { toast("收藏失败"); }
        render();
    }

    function closePanel() {
        setLast(true);
        const btn = document.querySelector('.chat-func-bar .icon-item[aria-label="表情"]');
        if (btn) btn.click();
        deactivate();
    }

    function send(cell, close) {
        const peer = peerNow();
        if (!peer) { toast("没有找到当前会话"); return; }
        const img = cell.querySelector("img");
        const hint = img ? { w: img.naturalWidth, h: img.naturalHeight } : null;
        if (close) closePanel();
        api.stickerSend(peer, cell.dataset.path, hint).then(res => {
            if (res && (res.error || (res.result !== undefined && res.result !== 0))) toast("发送失败：" + (res.error || res.errMsg || res.result));
        }).catch(() => toast("发送失败"));
    }

    function render() {
        if (!view) return;
        tabsEl.innerHTML = "";
        const tabs = [{ id: FAV, name: "收藏" }].concat(data.groups.map(g => ({ id: g.name, name: g.name, cover: g.files[0] })));
        for (const it of tabs) {
            const b = document.createElement("button");
            b.type = "button";
            b.className = "qe-sp-tab" + (it.id === tab ? " is-active" : "") + (it.id === FAV ? " is-fav-tab" : "");
            b.dataset.tab = it.id;
            b.title = it.name;
            if (it.id === FAV) b.innerHTML = STAR_BIG;
            else {
                b.draggable = true;
                b.title = it.name + "（拖动可调整顺序）";
                const img = document.createElement("img");
                img.loading = "lazy";
                img.draggable = false;
                img.src = appimg(it.cover);
                b.appendChild(img);
            }
            tabsEl.appendChild(b);
        }
        const cur = tabsEl.querySelector(".is-active");
        // 只滚底栏自己：scrollIntoView 会连带滚动外层，QQ 看到滚动就把表情面板收起了
        if (cur) {
            const l = cur.offsetLeft - tabsEl.offsetLeft, rgt = l + cur.offsetWidth;
            if (l < tabsEl.scrollLeft) tabsEl.scrollLeft = l;
            else if (rgt > tabsEl.scrollLeft + tabsEl.clientWidth) tabsEl.scrollLeft = rgt - tabsEl.clientWidth;
        }
        const files = tab === FAV ? data.favs : ((data.groups.find(g => g.name === tab) || {}).files || []);
        grid.innerHTML = "";
        const title = document.createElement("div");
        title.className = "qe-sp-title";
        title.textContent = (tab === FAV ? "收藏" : tab) + (files.length ? " · " + files.length : "");
        grid.appendChild(title);
        if (!files.length) {
            const empty = document.createElement("div");
            empty.className = "qe-sp-empty";
            if (tab === FAV) empty.innerHTML = data.groups.length
                ? "还没有收藏<br>在表情上点右上角的星标，或右键它，就会收进这里"
                : "表情文件夹是空的<br>点右下角<b>文件夹</b>按钮，把图片放进去<br>每个子文件夹会成为一个分组";
            else empty.textContent = "这个分组里没有图片";
            grid.appendChild(empty);
            return;
        }
        const frag = document.createDocumentFragment();
        for (const p of files) {
            const cell = document.createElement("div");
            cell.className = "qe-sp-cell" + (favSet.has(p) ? " is-fav" : "");
            cell.dataset.path = p;
            cell.title = p.split(/[\\/]/).pop().replace(/\.[^.]+$/, "");
            const img = document.createElement("img");
            img.loading = "lazy";
            img.decoding = "async";
            img.draggable = false;
            img.src = appimg(p);
            const star = document.createElement("div");
            star.className = "qe-sp-star";
            star.title = favSet.has(p) ? "取消收藏" : "收藏";
            star.innerHTML = STAR;
            cell.appendChild(img);
            cell.appendChild(star);
            frag.appendChild(cell);
        }
        grid.appendChild(frag);
    }

    // 整个盖住 QQ 的表情面板（内容区 + 分类栏）
    function place() {
        const sp = stickerPanel();
        if (!sp) return false;
        const r = sp.getBoundingClientRect();
        view.style.left = Math.round(r.left) + "px";
        view.style.top = Math.round(r.top) + "px";
        view.style.width = Math.round(r.width) + "px";
        view.style.height = Math.round(r.height) + "px";
        view.style.borderRadius = getComputedStyle(sp.closest(".expression-panel") || sp).borderRadius;
        return true;
    }

    function follow() {
        raf = 0;
        if (!active) return;
        if (!place()) { setLast(true); deactivate(); return; }
        raf = requestAnimationFrame(follow);
    }

    function markTab(on) {
        const tc = document.querySelector(".expression-panel .tabs-container");
        if (!tc) return;
        const mine = document.querySelector(".expression-panel .qe-st-tab");
        if (on) {
            tc.querySelectorAll("." + ACTIVE_CLS).forEach(n => { if (n !== mine) { n.classList.remove(ACTIVE_CLS); n.dataset.qeWasActive = "1"; } });
            if (mine) { mine.classList.add(ACTIVE_CLS); mine.setAttribute("aria-pressed", "true"); }
        } else {
            if (mine) { mine.classList.remove(ACTIVE_CLS); mine.setAttribute("aria-pressed", "false"); }
            tc.querySelectorAll("[data-qe-was-active]").forEach(n => { n.classList.add(ACTIVE_CLS); delete n.dataset.qeWasActive; });
        }
    }

    function activate() {
        build();
        active = true;
        document.body.classList.add("qe-st-active");
        markTab(true);
        if (place()) view.classList.add("is-open");
        render();
        reload();                                       // 每次切过来都重扫一遍，刚放进去的图马上能看到
        if (!raf) raf = requestAnimationFrame(follow);
    }

    function deactivate() {
        active = false;
        document.body.classList.remove("qe-st-active");
        if (view) view.classList.remove("is-open");
        markTab(false);
    }

    // 点 QQ 自带的分类：回到 QQ 的内容
    document.addEventListener("click", e => {
        const item = e.target.closest && e.target.closest(".expression-panel .tabs-container-item");
        if (!item) return;
        if (item.classList.contains("qe-st-tab")) {
            e.stopPropagation();
            e.preventDefault();
            if (!active) activate();
            return;
        }
        if (active) { setLast(false); deactivate(); }
    }, true);
    document.addEventListener("keydown", e => { if (e.key === "Escape" && active) { setLast(true); deactivate(); } }, true);
    addEventListener("hashchange", () => { if (active) { setLast(true); deactivate(); } });
    // 点输入框上的「表情」按钮：面板可能只是显示/隐藏，不触发 DOM 增删，主动看几次
    document.addEventListener("click", e => {
        if (!(e.target.closest && e.target.closest('.chat-func-bar .icon-item[aria-label="表情"]'))) return;
        [60, 200, 400].forEach(ms => setTimeout(ensureTab, ms));
    }, true);

    function applyNativeTabs() {
        const cfg = getConfig();
        for (const [key, , id] of NATIVE_TABS) {
            const attr = "data-qe-hide-" + id;
            const hide = cfg[key] === false;
            if (document.body.hasAttribute(attr) !== hide) document.body.toggleAttribute(attr, hide);
        }
    }

    function ensureTab() {
        applyNativeTabs();
        const bar = document.querySelector(".expression-panel .sticker-panel__bar");
        const tc = bar && bar.querySelector(".tabs-container");
        const on = !!getConfig().stickers;
        // 面板开/关要在任何提前 return 之前记下：面板关掉时底栏也没了，
        // 以前会直接 return，panelWasOpen 一直停在 true，下次打开就认不出“刚打开”
        const open = !!(on && tc && stickerPanel());
        const justOpened = open && !panelWasOpen;
        panelWasOpen = open;
        // 底栏出来了但面板还在展开动画里（尺寸不够）：过一会再看一次
        if (on && tc && !open) {
            if (!recheck) { if (recheckLeft <= 0) recheckLeft = 10; recheck = setTimeout(() => { recheck = 0; recheckLeft--; if (recheckLeft > 0) ensureTab(); }, 60); }
        } else recheckLeft = 0;
        const old = document.querySelectorAll(".qe-st-tab");
        if (!on || !tc) { old.forEach(n => n.remove()); if (!on && active) deactivate(); return; }
        if (old.length === 1 && bar.firstElementChild !== old[0]) bar.prepend(old[0]);   // Vue 重排后可能被挤到后面
        if (!(old.length === 1 && bar.contains(old[0]))) {
            old.forEach(n => n.remove());
            const item = document.createElement("div");
            item.className = "tabs-container-item qe-st-tab";
            item.setAttribute("role", "button");
            item.setAttribute("aria-label", LABEL);
            item.setAttribute("aria-pressed", "false");
            item.title = LABEL;
            item.tabIndex = -1;
            item.innerHTML = ICON;
            // 带上 QQ 分类按钮的 scoped 属性（data-v-xxx），图标颜色等样式和原生的一致
            const sib = tc.querySelector(".tabs-container-item");
            if (sib) for (const a of sib.attributes) if (a.name.startsWith("data-v-")) item.setAttribute(a.name, "");
            bar.prepend(item);
        }
        if (active) markTab(true);                      // QQ 重渲染时会把它自己那项重新点亮
        // 面板刚打开：上次停在本地表情页就切回来
        if (justOpened && lastOursVal && !active) activate();
    }

    return { ensure: ensureTab, reload, hide: deactivate };
}


/* QQ 增强 · SnowLora 适配版：Vue 实例桥
 * 原插件依赖 LiteLoader renderer hook 注入的 element.__VUE__。
 * SnowLora 没有这个 hook，这里从 #app.__vue_app__ 的根 vnode 反向遍历，
 * 把组件实例回填到对应 DOM 元素上；之后新挂载的组件由 MutationObserver + 定时器补。
 * 实测 QQ 9.9.36：.message.__VUE__[0].props.msgRecord 可正常取到。
 */
(() => {
  if (window.__qeVueBridge) return;
  window.__qeVueBridge = true;

  function mapVue() {
    try {
      const appEl = document.getElementById('app');
      const app = appEl && appEl.__vue_app__;
      const root = app && app._container && app._container._vnode;
      if (!root) return 0;
      let count = 0;
      const seen = new Set();
      const walk = (vnode, depth) => {
        if (!vnode || typeof vnode !== 'object' || depth > 80 || seen.has(vnode)) return;
        seen.add(vnode);
        if (vnode.__v_isVNode) {
          const el = vnode.el;
          if (el && el.nodeType === 1) {
            if (!el.__VUE__) el.__VUE__ = [];
            if (vnode.component && !el.__VUE__.includes(vnode.component)) {
              el.__VUE__.push(vnode.component);
              count++;
            }
          }
          if (vnode.component) walk(vnode.component.subTree, depth + 1);
          if (Array.isArray(vnode.children)) {
            for (const child of vnode.children) walk(child, depth + 1);
          } else if (vnode.children && typeof vnode.children === 'object' && vnode.children.__v_isVNode) {
            walk(vnode.children, depth + 1);
          }
          if (vnode.suspense) walk(vnode.suspense.activeBranch, depth + 1);
        }
      };
      walk(root, 0);
      return count;
    } catch (e) {
      return 0;
    }
  }

  window.__qeMapVue = mapVue;
  mapVue();
  let timer = 0;
  const schedule = () => {
    if (timer) return;
    timer = setTimeout(() => {
      timer = 0;
      mapVue();
    }, 100);
  };
  try {
    new MutationObserver(schedule).observe(document.documentElement, { childList: true, subtree: true });
  } catch (e) {}
  setInterval(mapVue, 2000);
})();


// QQ 增强 · 界面
//   1. 防撤回：给已还原的消息打「已撤回」标记
//   2. 记住浏览位置：切回会话时停在上次看到的地方（Telegram 的做法）
//   3. 右键菜单「复读」：把这条消息原样再发一次
//   4. 引用时不带 @：点「引用」后删掉 QQ 自动插入的 @
//   5. 本地表情包：表情文件夹按子文件夹分组，另有一个收藏分组（见 stickers.js）
//   6. 设置页：每项单独开关
// 消息数据从 .message 元素上的 __VUE__[0].props.msgRecord 读（QQ 9.9.36 实测）。

const api = window.qq_enhance;
let config = { antiRecall: true, chatPos: true, repeat: true, pokeNoCd: false, quoteNoAt: true, arkExternal: true, pangu: true, stickers: true, stickerDir: "", showEmojiSearch: true, showEmojiDefault: true, showEmojiFav: true };
let stickers = null;

function recordOf(el) {
    try {
        const m = el && el.closest && el.closest(".message");
        const inst = m && m.__VUE__ && m.__VUE__[0];
        return (inst && inst.props && inst.props.msgRecord) || null;
    } catch (e) { return null; }
}

function toast(text) {
    let el = document.getElementById("qq-enhance-toast");
    if (!el) {
        el = document.createElement("div");
        el.id = "qq-enhance-toast";
        el.style.cssText = "position:fixed;left:50%;bottom:96px;transform:translateX(-50%);z-index:99999;" +
            "padding:6px 14px;border-radius:10px;font-size:13px;pointer-events:none;opacity:0;transition:opacity 160ms;" +
            "background:var(--ll-float-bg, rgba(30,30,30,0.9));color:var(--ll-on-glass, #fff);box-shadow:0 4px 16px rgba(0,0,0,0.3)";
        document.body.appendChild(el);
    }
    el.textContent = text;
    el.style.opacity = "1";
    clearTimeout(el._t);
    el._t = setTimeout(() => { el.style.opacity = "0"; }, 1600);
}

/* ════════════════ 1. 防撤回标记 ════════════════ */
const recalled = new Map();   // msgId -> 撤回人
const AR_CSS = `
.ml-item.ar-recalled .message-content__wrapper {
  position: relative;
  opacity: 0.78;
  outline: 1.5px dashed var(--ll-brand, var(--brand_standard, #1d9bf0));
  outline-offset: 2px;
  border-radius: 10px;
}
.ml-item.ar-recalled .message-content__wrapper::after {
  content: "已撤回 · " attr(data-ar-by);
  display: block;
  margin-top: 4px;
  font-size: 11px;
  line-height: 16px;
  color: var(--ll-brand, var(--brand_standard, #1d9bf0));
  white-space: nowrap;
}`;

function markRecalled() {
    if (!recalled.size) return;
    const items = document.querySelectorAll(".ml-item[id]");
    for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const nick = recalled.get(item.id);
        if (nick === undefined) {
            if (item.classList.contains("ar-recalled")) item.classList.remove("ar-recalled");
            continue;
        }
        if (!item.classList.contains("ar-recalled")) item.classList.add("ar-recalled");
        const wrap = item.querySelector(".message-content__wrapper");
        if (wrap && wrap.dataset.arBy !== nick) wrap.dataset.arBy = nick;
    }
}

function reloadRecalled() {
    api.recalledList().then(map => {
        recalled.clear();
        for (const [id, nick] of Object.entries(map || {})) recalled.set(id, nick);
        markRecalled();
        // 清空后要把旧标记去掉
        if (!recalled.size) document.querySelectorAll(".ml-item.ar-recalled").forEach(x => x.classList.remove("ar-recalled"));
    }).catch(() => {});
}

/* ════════════════ 2. 记住浏览位置 ════════════════
 * 记：滚动停下 300ms 后，记下视口最上面那条消息的 id 和它离视口顶的距离；
 *     当时就在最底下则记「在底部」，回来时什么都不做（QQ 默认就在底部）。
 * 回：切换会话后等 QQ 先渲染，再找那条消息：找到就滚回原位置；
 *     找不到就往上翻一屏让 QQ 加载更早的消息，最多翻 40 次。用户一滚动/点击就停手。 */
const POS_KEY = "qq-enhance-chat-pos";
const POS_MAX = 300;
const BOTTOM_PX = 48;
let posStore = {};
try { posStore = JSON.parse(localStorage.getItem(POS_KEY) || "{}"); } catch (e) { posStore = {}; }

function savePosStore() {
    const ids = Object.keys(posStore);
    if (ids.length > POS_MAX) ids.sort((a, b) => posStore[a].t - posStore[b].t).slice(0, ids.length - POS_MAX).forEach(k => delete posStore[k]);
    try { localStorage.setItem(POS_KEY, JSON.stringify(posStore)); } catch (e) {}
}

function currentPeer() {
    const rec = recordOf(document.querySelector(".chat-msg-area .message"));
    return rec ? rec.chatType + ":" + rec.peerUid : "";
}

function findScroller() {
    const area = document.querySelector(".chat-msg-area");
    if (!area) return null;
    const item = area.querySelector(".ml-item");
    for (let n = item && item.parentElement; n && n !== document.body; n = n.parentElement) {
        const oy = getComputedStyle(n).overflowY;
        // QQ 的消息列表（.q-scroll-view）用的是 overflow-y: overlay，不认它就一次都记不上
        if ((oy === "auto" || oy === "scroll" || oy === "overlay") && n.scrollHeight > n.clientHeight + 4) return n;
        if (n === area) break;
    }
    return null;
}

function distanceToBottom(sc) {
    // 倒序列表（column-reverse）在底部时 scrollTop 是 0、往上是负数
    if (sc.scrollTop < 0 || getComputedStyle(sc).flexDirection === "column-reverse") return -sc.scrollTop;
    return sc.scrollHeight - sc.scrollTop - sc.clientHeight;
}

function topVisibleItem(sc) {
    const top = sc.getBoundingClientRect().top;
    let best = null, bestTop = Infinity;
    const items = sc.querySelectorAll(".ml-item[id]");
    for (let i = 0; i < items.length; i++) {
        const r = items[i].getBoundingClientRect();
        if (r.bottom <= top + 4) continue;
        if (r.top < bestTop) { bestTop = r.top; best = items[i]; }
    }
    return best ? { id: best.id, off: Math.round(bestTop - top) } : null;
}

let peer = "";
let restoring = false;
let posSaveTimer = 0;
let restoreJob = 0;

function savePos() {
    if (!config.chatPos || restoring || !peer) return;
    // 界面已经换成别的会话（QQ 切会话时会把新会话滚到底并触发 scroll），
    // 这时再记就会把「在底部」错记到旧会话头上，把真正的位置冲掉
    if (currentPeer() !== peer) return;
    const sc = findScroller();
    if (!sc) return;
    if (distanceToBottom(sc) <= BOTTOM_PX) posStore[peer] = { bottom: true, t: Date.now() };
    else {
        const a = topVisibleItem(sc);
        if (!a) return;
        posStore[peer] = { id: a.id, off: a.off, t: Date.now() };
    }
    savePosStore();
}

document.addEventListener("scroll", e => {
    if (restoring || !config.chatPos) return;
    const t = e.target;
    if (!t || !t.closest || !t.closest(".chat-msg-area")) return;
    clearTimeout(posSaveTimer);
    posSaveTimer = setTimeout(savePos, 300);
}, { capture: true, passive: true });

function stopRestore() { restoring = false; restoreJob++; }
// 点会话列表等地方之前，先把还没来得及记的位置立刻记下（滚完 300ms 内就切走也不丢）
document.addEventListener("mousedown", e => {
    if (!posSaveTimer || restoring) return;
    if (e.target && e.target.closest && e.target.closest(".chat-msg-area")) return;
    clearTimeout(posSaveTimer); posSaveTimer = 0;
    savePos();
}, true);
["wheel", "mousedown", "keydown", "touchstart"].forEach(ev =>
    document.addEventListener(ev, e => { if (restoring && e.isTrusted) stopRestore(); }, { capture: true, passive: true }));

function restorePos(target) {
    const job = ++restoreJob;
    restoring = true;
    let tries = 0;
    // QQ 的消息列表是虚拟列表：直接改 scrollTop 它不认，要用它自己暴露的方法。
    // 从一条消息的 Vue 实例往上找：带 scrollToMsg 的是消息列表，带 scrollTo/getScrollTop 的是滚动容器。
    const apis = () => {
        const m = document.querySelector(".chat-msg-area .message");
        let inst = m && m.__VUE__ && m.__VUE__[0];
        let list = null, view = null;
        for (let d = 0; inst && d < 8; d++, inst = inst.parent) {
            const ex = inst.exposed;
            if (!ex) continue;
            if (!view && typeof ex.scrollTo === "function" && typeof ex.getScrollTop === "function") view = ex;
            if (!list && typeof ex.scrollToMsg === "function") list = ex;
        }
        return list ? { list, view } : null;
    };
    const loaded = list => {
        const m = list.msgs;
        const arr = (m && m.value) || m || [];
        return Array.isArray(arr) && arr.some(x => x && x.msgId === target.id);
    };
    const step = () => {
        if (job !== restoreJob) return;
        const sc = findScroller();
        const a = apis();
        if (!sc || !a) { if (tries++ < 40) return setTimeout(step, 150); return stopRestore(); }
        if (loaded(a.list)) {
            let ok = false;
            try { ok = a.list.scrollToMsg(target.id); } catch (e) {}
            Promise.resolve(ok).finally(() => setTimeout(() => { if (job === restoreJob) restoring = false; }, 300));
            return;
        }
        if (tries++ >= 40) return stopRestore();
        // 往上翻一屏，让 QQ 加载更早的消息
        sc.scrollTop -= sc.clientHeight;
        setTimeout(step, 350);
    };
    setTimeout(step, 350);
}

function checkPeer() {
    const p = currentPeer();
    if (!p || p === peer) return;
    stopRestore();                                         // 此时界面已是新会话，不能再给旧会话补记
    peer = p;
    const saved = posStore[p];
    if (config.chatPos && saved && !saved.bottom && saved.id) restorePos(saved);
}

/* ════════════════ 3. 右键菜单「复读」 ════════════════
 * 记下右键的是哪条消息；菜单出现后在「转发」后面克隆一项「复读」。 */
const REPEAT_ICON = '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M7 7h10v3l4-4-4-4v3H5v6h2V7zm10 10H7v-3l-4 4 4 4v-3h12v-6h-2v4z"/></svg>';
let ctxMsg = null;

document.addEventListener("contextmenu", e => {
    if (!config.repeat) { ctxMsg = null; return; }
    const rec = recordOf(e.target);
    // 只传几个字段：msgRecord 是 Vue 响应式对象，不能直接走 IPC
    ctxMsg = rec ? { msgId: String(rec.msgId), chatType: rec.chatType, peerUid: String(rec.peerUid), guildId: rec.guildId ? String(rec.guildId) : "" } : null;
    if (ctxMsg) setTimeout(injectRepeat, 0);
}, true);

function menuItemByText(menu, text) {
    const items = menu.querySelectorAll(".q-context-menu-item");
    for (let i = 0; i < items.length; i++) if ((items[i].textContent || "").trim() === text) return items[i];
    return null;
}

function injectRepeat(tries) {
    tries = tries || 0;
    const menu = document.querySelector(".q-context-menu");
    if (!menu || !ctxMsg) { if (tries < 10) setTimeout(() => injectRepeat(tries + 1), 30); return; }
    if (menu.querySelector(".qe-repeat-item")) return;
    const anchor = menuItemByText(menu, "转发") || menuItemByText(menu, "复制");
    if (!anchor) return;
    const item = anchor.cloneNode(true);
    item.classList.add("qe-repeat-item");
    item.classList.remove("q-context-menu-item--disabled");
    const label = item.querySelector(".q-context-menu-item__text");
    if (label) label.textContent = "复读";
    const icon = item.querySelector("svg");
    if (icon && icon.parentElement) icon.parentElement.innerHTML = REPEAT_ICON;
    const msg = ctxMsg;
    item.addEventListener("click", ev => {
        ev.stopPropagation();
        ev.preventDefault();
        menu.style.display = "none";
        document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
        document.body.dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));
        api.repeat(msg).then(res => {
            if (res && (res.error || (res.result !== undefined && res.result !== 0))) toast("复读失败：" + (res.error || res.errMsg || res.result));
        }).catch(() => toast("复读失败"));
    }, true);
    anchor.after(item);
}

/* ════════════════ 4. 戳一戳无冷却 ════════════════
 * 右键头像点「戳一戳」时把界面自己的处理截下来，改走内核接口，不受 10 秒冷却限制。
 * 目标从右键的那条消息里取；认不出目标就不插手，交给 QQ 自己。 */
let pokeCtx = null;
let pokeAt = 0;

document.addEventListener("contextmenu", e => {
    if (!config.pokeNoCd) { pokeCtx = null; return; }
    const rec = recordOf(e.target);
    // 只处理私聊/群聊；频道、临时会话等其它类型交回 QQ 自己处理
    const ct = rec && Number(rec.chatType);
    if (!rec || (ct !== 1 && ct !== 2) || !rec.senderUid || !rec.peerUid) { pokeCtx = null; return; }
    pokeCtx = {
        chatType: rec.chatType,
        peerUid: String(rec.peerUid),
        peerUin: rec.peerUin ? String(rec.peerUin) : "",
        guildId: rec.guildId ? String(rec.guildId) : "",
        targetUin: rec.senderUin ? String(rec.senderUin) : "",
    };
}, true);

function closeContextMenu() {
    const menu = document.querySelector(".q-context-menu");
    if (menu) menu.style.display = "none";
    document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
    document.body.dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));
}

/* 四个事件都拦：QQ 用哪个触发菜单项不确定，命中一次就够；pointer 事件也要拦，否则 QQ 若监听
 * pointerdown 会和我们各发一次 */
for (const type of ["pointerdown", "mousedown", "mouseup", "click"]) {
    document.addEventListener(type, e => {
        if (!config.pokeNoCd || !pokeCtx || !pokeCtx.targetUin) return;
        const item = e.target && e.target.closest && e.target.closest(".q-context-menu-item");
        if (!item || (item.textContent || "").trim() !== "戳一戳") return;
        e.stopImmediatePropagation();
        e.preventDefault();
        if (Date.now() - pokeAt < 400) return;
        pokeAt = Date.now();
        const ctx = pokeCtx;
        closeContextMenu();
        api.poke(ctx).then(res => {
            if (res && (res.error || (res.result !== undefined && res.result !== 0))) {
                toast("戳一戳失败：" + (res.error || res.errMsg || res.result));
            }
        }).catch(() => toast("戳一戳失败"));
    }, true);
}

/* ════════════════ 5. 引用时不带 @ ════════════════
 * 点「引用」后，QQ 往输入框里插：引用块 .editor-el__reply-wrapper + <p>@某人 </p>。
 * 实测：@ 是 <span class="editor-el__at" contenteditable="false">，后跟一个空格。
 * 点「引用」后 1.5 秒内，一出现紧跟引用块的 @，就把它和后面的空格删掉；
 * ProseMirror 会把这次 DOM 改动读回自己的文档（与用户删字走同一条路）。 */
let quoteUntil = 0;

/* 入口一：右键菜单点「引用」 */
document.addEventListener("click", e => {
    if (!config.quoteNoAt) return;
    const item = e.target && e.target.closest && e.target.closest(".q-context-menu-item");
    if (!item || (item.textContent || "").trim() !== "引用") return;
    quoteUntil = Date.now() + 1500;
    watchQuoteAt();
}, true);

/* 入口二：双击消息引用（不走右键菜单） */
document.addEventListener("dblclick", e => {
    if (!config.quoteNoAt) return;
    const t = e.target;
    if (!t || !t.closest || !t.closest(".chat-msg-area, .message-container")) return;
    quoteUntil = Date.now() + 1500;
    // 只等「新出现」的引用块：草稿里已有的 @ 是用户自己打的，不能动
    watchQuoteAt(false);
}, true);

/* 入口兜底：编辑器里一出现引用块就剥紧跟的 @，不管引用是从哪触发的 */
let quoteObs = null;
let quoteObsTarget = null;
let lastReplyWrap = null;

function installQuoteWatch() {
    if (!config.quoteNoAt) {
        if (quoteObs) { quoteObs.disconnect(); quoteObs = null; quoteObsTarget = null; lastReplyWrap = null; }
        return;
    }
    const pm = editorEl();
    if (!pm) return;
    if (quoteObs && quoteObsTarget === pm && pm.isConnected) return;
    if (quoteObs) quoteObs.disconnect();
    quoteObsTarget = pm;
    lastReplyWrap = null;
    quoteObs = new MutationObserver(() => {
        if (!config.quoteNoAt) return;
        const wrap = pm.querySelector(".editor-el__reply-wrapper");
        if (!wrap || wrap === lastReplyWrap) return;
        lastReplyWrap = wrap;
        quoteUntil = Date.now() + 1500;
        watchQuoteAt();
    });
    quoteObs.observe(pm, { childList: true, subtree: true });
}

function editorEl() {
    return document.querySelector(".chat-input-area .ProseMirror") || document.querySelector(".ProseMirror");
}

function stripQuoteAt() {
    const pm = editorEl();
    if (!pm || !pm.querySelector(".editor-el__reply-wrapper")) return false;
    const p = pm.querySelector(".editor-el__reply-wrapper ~ p");
    if (!p) return false;
    const at = p.querySelector(".editor-el__at");
    if (!at) return false;
    // @ 必须是这个段落里第一个「有内容」的节点；跳过 ProseMirror 的占位 widget
    let node = p.firstChild;
    while (node && node !== at) {
        if (node.nodeType === 3 && !node.data.trim()) { node = node.nextSibling; continue; }
        if (node.nodeType === 1 && /exeditor-placeholder|ProseMirror-widget|ProseMirror-separator/.test(String(node.className || ""))) {
            node = node.nextSibling;
            continue;
        }
        return false;
    }
    if (node !== at) return false;
    const next = at.nextSibling;
    at.remove();
    if (next && next.nodeType === 3) {
        next.data = next.data.replace(/^[\s\u00a0]/, "");
        if (!next.data) next.remove();
    }
    if (!p.childNodes.length) p.appendChild(document.createElement("br"));
    pm.focus();
    return true;
}

function watchQuoteAt(allowExisting) {
    const pm = editorEl();
    if (!pm) return;
    // 入口一/兜底 observer：引用块已经出现，立刻剥；双击入口传 false，不能动草稿里已有的 @
    if (allowExisting !== false && stripQuoteAt()) return;
    const ob = new MutationObserver(() => {
        if (Date.now() > quoteUntil) { ob.disconnect(); return; }
        if (stripQuoteAt()) ob.disconnect();
    });
    ob.observe(pm, { childList: true, subtree: true });
    setTimeout(() => ob.disconnect(), 1600);
}

/* ════════════════ 6. 卡片用外部浏览器打开 ════════════════
 * B 站等分享的「QQ小程序」卡片，QQ 会去开小程序。QQ 被 LiteLoader 改过文件，
 * 小程序自检失败，只弹「文件已损坏」。这里先截下点击，从卡片数据里取网页链接，交给默认浏览器。
 * 卡片是一块 canvas，点击在 document 捕获阶段拦掉，QQ 自己就收不到。 */
function arkUrl(rec) {
    const el = rec && Array.isArray(rec.elements) && rec.elements.find(x => x && x.arkElement);
    if (!el) return "";
    let data;
    try { data = JSON.parse(el.arkElement.bytesData); } catch (e) { return ""; }
    const meta = (data && data.meta) || {};
    const fix = u => {
        u = String(u || "").trim();
        if (!u) return "";
        if (!/^[a-z]+:\/\//i.test(u)) u = "https://" + u.replace(/^\/+/, "");
        return /^https?:\/\//i.test(u) ? u : "";
    };
    for (const v of Object.values(meta)) {
        if (!v || typeof v !== "object") continue;
        const u = fix(v.qqdocurl) || fix(v.jumpUrl) || fix(v.url);
        if (u) return u;
    }
    return "";
}

function arkTarget(e) {
    if (!config.arkExternal || e.button !== 0) return null;
    const card = e.target && e.target.closest && e.target.closest(".ark-msg-content-container .ark-item-container");
    if (!card) return null;
    return arkUrl(recordOf(card)) || null;
}

["pointerdown", "mousedown", "pointerup", "mouseup", "click", "dblclick"].forEach(type =>
    document.addEventListener(type, e => {
        const url = arkTarget(e);
        if (!url) return;
        e.preventDefault();
        e.stopImmediatePropagation();
        if (type === "click") api.openExternal(url).then(ok => toast(ok ? "已用浏览器打开" : "打不开这个链接")).catch(() => {});
    }, true));

/* ════════════════ 启动 ════════════════ */
function start() {
    if (!api || window.__qqEnhanceStarted) return;
    window.__qqEnhanceStarted = true;

    const style = document.createElement("style");
    style.id = "qq-enhance-style";
    style.textContent = AR_CSS;
    (document.head || document.documentElement).appendChild(style);

    api.getConfig().then(cfg => { if (cfg) config = cfg; }).catch(() => {});
    api.onConfigChanged(cfg => { if (cfg) config = cfg; reloadRecalled(); if (stickers) { stickers.ensure(); stickers.reload(); } });
    reloadRecalled();
    api.onRecalled((id, nick) => { recalled.set(String(id), nick || "对方"); markRecalled(); });
    if (location.hash.indexOf("#/setting") !== 0) stickers = installStickers(api, () => config, toast);

    // DOM 变动后 150ms 跑一次（滚动时合并成一次，不每帧跑）
    let timer = 0;
    new MutationObserver(() => {
        if (timer) return;
        timer = setTimeout(() => { timer = 0; markRecalled(); checkPeer(); installQuoteWatch(); if (stickers) stickers.ensure(); }, 150);
    }).observe(document.body, { childList: true, subtree: true });

    installQuoteWatch();
}

if (document.body) start();
else addEventListener("DOMContentLoaded", start);

/* ════════════════ 5. 设置页 ════════════════
 * 用 LiteLoader 自带的 setting-* 组件，样式跟其他插件设置一致。 */
const FEATURES = [
    ["antiRecall", "防撤回", "别人撤回的消息照常显示，标上「已撤回」。只能还原插件运行时收到过的消息。"],
    ["chatPos", "记住浏览位置", "切回会话时停在上次看到的地方，而不是跳到最底下。"],
    ["repeat", "右键复读", "消息右键菜单里加一项「复读」，把这条消息原样再发一次。"],
    ["pokeNoCd", "戳一戳无冷却", "右键点头像「戳一戳」不再受 10 秒冷却限制，可以连续戳。默认关闭，需要时在这里打开。"],
    ["quoteNoAt", "引用时不带 @", "点「引用」或双击消息引用时，不自动在输入框里插入 @对方。"],
    ["pangu", "发送时自动 pangu", "中英文、中文与数字之间自动补空格。消息开头打两个逗号（,, 或 ，，）则这条不处理，逗号本身也会去掉。"],
    ["arkExternal", "卡片用浏览器打开", "点 B 站等分享卡片（QQ小程序），用电脑默认浏览器打开网页，不再弹「文件已损坏」。"],
    ["stickers", "本地表情包", "表情面板底部多一个「本地表情」分类，发送表情文件夹里的图片。每个子文件夹是一个分组，另有收藏分组。"],
];

function fmtBytes(n) {
    if (n < 1024) return n + " B";
    if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB";
    return (n / 1024 / 1024).toFixed(1) + " MB";
}

async function onSettingWindowCreated(view) {
    let cfg = config;
    try { cfg = (await api.getConfig()) || cfg; } catch (e) {}

    view.innerHTML = `
<setting-section data-title="功能">
  <setting-panel>
    <setting-list data-direction="column" class="qe-features"></setting-list>
  </setting-panel>
</setting-section>
<setting-section data-title="本地表情包">
  <setting-panel>
    <setting-list data-direction="column" class="qe-st-list">
      <setting-item>
        <div>
          <setting-text>表情文件夹</setting-text>
          <setting-text data-type="secondary" class="qe-st-dir">读取中…</setting-text>
        </div>
        <div style="display:flex;gap:8px">
          <setting-button data-type="secondary" class="qe-st-open">打开</setting-button>
          <setting-button data-type="secondary" class="qe-st-pick">更换</setting-button>
          <setting-button data-type="secondary" class="qe-st-reset" style="display:none">恢复默认</setting-button>
        </div>
      </setting-item>
    </setting-list>
  </setting-panel>
</setting-section>
<setting-section data-title="防撤回数据">
  <setting-panel>
    <setting-list data-direction="column">
      <setting-item>
        <div>
          <setting-text>已保存的原文</setting-text>
          <setting-text data-type="secondary" class="qe-stats">读取中…</setting-text>
        </div>
        <setting-button data-type="secondary" class="qe-clear">清空</setting-button>
      </setting-item>
    </setting-list>
  </setting-panel>
</setting-section>`;

    const list = view.querySelector(".qe-features");
    for (const [key, name, desc] of FEATURES) {
        const item = document.createElement("setting-item");
        item.innerHTML = `<div><setting-text></setting-text><setting-text data-type="secondary"></setting-text></div><setting-switch></setting-switch>`;
        const texts = item.querySelectorAll("setting-text");
        texts[0].textContent = name;
        texts[1].textContent = desc;
        const sw = item.querySelector("setting-switch");
        sw.toggleAttribute("is-active", !!cfg[key]);
        sw.addEventListener("click", async () => {
            const on = !sw.hasAttribute("is-active");
            sw.toggleAttribute("is-active", on);
            try { cfg = await api.setConfig({ [key]: on }); } catch (e) { sw.toggleAttribute("is-active", !on); }
        });
        list.appendChild(item);
    }

    // 表情面板里 QQ 自带的三个按钮：可以分别隐藏
    const stList = view.querySelector(".qe-st-list");
    for (const [key, label] of NATIVE_TABS) {
        const item = document.createElement("setting-item");
        item.innerHTML = `<div><setting-text></setting-text><setting-text data-type="secondary"></setting-text></div><setting-switch></setting-switch>`;
        const texts = item.querySelectorAll("setting-text");
        texts[0].textContent = "表情面板显示「" + label + "」";
        texts[1].textContent = "关掉后，表情面板底栏不再显示 QQ 自带的这个按钮。";
        const sw = item.querySelector("setting-switch");
        sw.toggleAttribute("is-active", cfg[key] !== false);
        sw.addEventListener("click", async () => {
            const on = !sw.hasAttribute("is-active");
            sw.toggleAttribute("is-active", on);
            try { cfg = await api.setConfig({ [key]: on }); } catch (e) { sw.toggleAttribute("is-active", !on); }
        });
        stList.appendChild(item);
    }

    const dirEl = view.querySelector(".qe-st-dir");
    const resetBtn = view.querySelector(".qe-st-reset");
    const refreshDir = () => api.stickerList().then(s => {
        const n = s.groups.reduce((a, g) => a + g.files.length, 0);
        dirEl.textContent = s.root + "（" + s.groups.length + " 个分组，" + n + " 张，收藏 " + s.favs.length + " 张）";
        resetBtn.style.display = s.isDefault ? "none" : "";
    }).catch(() => { dirEl.textContent = "读取失败"; });
    refreshDir();
    view.querySelector(".qe-st-open").addEventListener("click", () => api.stickerOpenDir());
    view.querySelector(".qe-st-pick").addEventListener("click", async () => {
        const c = await api.stickerPickDir();
        if (c) { cfg = c; refreshDir(); }
    });
    resetBtn.addEventListener("click", async () => {
        cfg = await api.setConfig({ stickerDir: "" });
        refreshDir();
    });

    const statsEl = view.querySelector(".qe-stats");
    const refreshStats = () => api.stats().then(s => {
        statsEl.textContent = s.saved + " 条，占用 " + fmtBytes(s.bytes) + "；已标记撤回 " + s.recalled + " 条";
    }).catch(() => { statsEl.textContent = "读取失败"; });
    refreshStats();

    const clearBtn = view.querySelector(".qe-clear");
    let armed = false;
    clearBtn.addEventListener("click", async () => {
        // 点两次才清：第一次变成确认
        if (!armed) {
            armed = true;
            clearBtn.textContent = "确定清空？";
            setTimeout(() => { armed = false; clearBtn.textContent = "清空"; }, 3000);
            return;
        }
        armed = false;
        clearBtn.textContent = "清空";
        await api.clearSaved();
        refreshStats();
    });
};


/* QQ 增强 · SnowLora 适配版：设置入口
 * 唯一入口：QQ 设置窗（#/setting）里的「QQ 增强」导航页——
 * 按 LiteLoader 的挂载方式克隆 .nav-item，
 * 内容放进 .setting-main .setting-main__content，点导航切页。
 * SnowLora 主进程在 browser-window-created 时就会 hook 设置窗，
 * 这里在 DOM 就绪后立刻挂载，不依赖标题匹配。
 * 主窗不再提供齿轮按钮 / 页内对话框：非设置窗直接返回，连样式都不注入。 */
(() => {
  if (window.__qqEnhanceSettingsUi) return;
  window.__qqEnhanceSettingsUi = true;
  if (location.hash.indexOf('#/setting') !== 0) return;
  if (!window.qq_enhance) return;
  if (typeof onSettingWindowCreated === 'function') window.__qeRenderSettings = onSettingWindowCreated;

  const CSS = `
.qe-settings-view setting-section { display: block; margin: 4px 0 18px; }
.qe-settings-view setting-section::before {
  content: attr(data-title); display: block; margin: 0 0 8px; font-size: 12px; font-weight: 600;
  letter-spacing: .04em; opacity: .55;
}
.qe-settings-view setting-panel,
.qe-settings-view setting-list { display: block; }
.qe-settings-view setting-item {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding: 10px 12px; border-radius: 10px; background: rgba(127,127,127,.08);
}
.qe-settings-view setting-item + setting-item { margin-top: 6px; }
.qe-settings-view setting-text { display: block; font-size: 13px; line-height: 1.5; }
.qe-settings-view setting-text[data-type="secondary"] { margin-top: 2px; font-size: 11.5px; opacity: .55; }
.qe-settings-view setting-switch {
  flex: 0 0 auto; position: relative; width: 36px; height: 20px; border-radius: 999px;
  background: rgba(127,127,127,.4); cursor: pointer; transition: background .15s;
}
.qe-settings-view setting-switch[is-active] { background: var(--ll-brand, #1d9bf0); }
.qe-settings-view setting-switch::after {
  content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px;
  border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(0,0,0,.35);
  transition: transform .15s;
}
.qe-settings-view setting-switch[is-active]::after { transform: translateX(16px); }
.qe-settings-view setting-button {
  display: inline-flex; align-items: center; justify-content: center; min-height: 26px; padding: 0 12px;
  border-radius: 8px; border: 1px solid rgba(127,127,127,.25); background: rgba(127,127,127,.1);
  color: inherit; font-size: 12px; cursor: pointer;
}
.qe-settings-view setting-button:hover { background: rgba(127,127,127,.18); }

.qe-settings-view { box-sizing: border-box; padding: 8px 26px 28px; }
.qe-settings-view::before { content: none; }
.qe-nav-item .name { font-size: 14px; }
`;
  const style = document.createElement('style');
  style.id = 'qq-enhance-ui-style';
  style.textContent = CSS;
  (document.head || document.documentElement).appendChild(style);

  /* ---------- 设置窗：挂到 QQ 设置页 ---------- */
  let tries = 0;
  let installed = false;
  const mount = () => {
    if (installed) return;
    const tab = document.querySelector('.setting-tab');
    const navBar = document.querySelector('.setting-tab .nav-bar');
    const main = document.querySelector('.setting-main .setting-main__content');
    const original = document.querySelector('.setting-main .q-scroll-view');
    const title = document.querySelector('.setting-main .setting-title');
    const sample = navBar && navBar.querySelector('.nav-item');
    if (!tab || !navBar || !main || !original || !title || !sample) {
      if (tries++ < 60) setTimeout(mount, 250);
      return;
    }
    const nav = sample.cloneNode(true);
    nav.classList.remove('nav-item-active');
    nav.classList.add('qe-nav-item');
    nav.removeAttribute('data-slug');
    const name = nav.querySelector('.name');
    if (name) name.textContent = 'QQ 增强';
    else nav.textContent = 'QQ 增强';
    const group = document.createElement('div');
    group.className = 'nav-bar qe-nav';
    group.append(nav);
    tab.append(group);

    const view = document.createElement('div');
    view.className = 'q-scroll-view scroll-view--show-scrollbar qe-settings-view';
    view.style.display = 'none';
    main.append(view);

    let titleNode = null;
    let titleSaved = null;
    const showOther = () => {
      view.style.display = 'none';
      original.style.display = 'block';
      if (titleNode && titleSaved !== null && titleNode.isConnected) titleNode.nodeValue = titleSaved;
      titleNode = null;
      titleSaved = null;
    };
    nav.addEventListener('click', async () => {
      if (!view.dataset.ready) {
        view.dataset.ready = '1';
        try {
          await window.__qeRenderSettings(view);
        } catch (e) {
          view.textContent = 'QQ 增强设置加载失败：' + (e && e.message ? e.message : e);
        }
      }
      original.style.display = 'none';
      view.style.display = 'block';
      // 标题是 <div.setting-title><div.icon-area/> 通用<!--v-if--></div>：改 icon-area 后面的文本节点。
      // childNodes[1] 是 icon-area 本身，改它会让标题变成「QQ 增强通用」。离开时还原，Vue 在值没变时不会重绘。
      const titleText = [...title.childNodes].find(n => n.nodeType === 3 && n.nodeValue.trim());
      if (titleText) {
        if (titleSaved === null) titleSaved = titleText.nodeValue;
        titleNode = titleText;
        titleText.nodeValue = ' QQ 增强';
      }
      tab.querySelectorAll('.nav-item').forEach(el => el.classList.remove('nav-item-active'));
      nav.classList.add('nav-item-active');
    });
    tab.addEventListener('click', e => {
      const item = e.target.closest && e.target.closest('.nav-item');
      if (item && item !== nav) showOther();
    }, true);
    installed = true;
  };
  mount();
})();
